import{_ as e,o as t,c as r,ag as o}from"./chunks/framework.D9ghT4bC.js";const u=JSON.parse('{"title":"场景制作","description":"","frontmatter":{"title":"场景制作"},"headers":[],"relativePath":"zh/Modders/Scenarios.md","filePath":"zh/Modders/Scenarios.md"}'),l={name:"zh/Modders/Scenarios.md"};function i(n,a,s,d,h,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="场景制作" tabindex="-1">场景制作 <a class="header-anchor" href="#场景制作" aria-label="Permalink to &quot;场景制作&quot;">​</a></h1><p>场景是特定的游戏状态，设置为让玩家获得特定的体验。</p><p>场景的范围可以从仅仅在城市和单位处于特定位置，到拥有完整的自定义规则集来支持它们。</p><p>创建模组时，我们将<em>规则集</em>与<em>场景</em>区分开来 - 场景只是特定的游戏状态，换句话说 - 就是一个保存的游戏。</p><h2 id="创建场景" tabindex="-1">创建场景 <a class="header-anchor" href="#创建场景" aria-label="Permalink to &quot;创建场景&quot;">​</a></h2><ul><li>创建一个新游戏，包含你想要的玩家，<strong>以及一个观察者</strong></li><li>作为观察者进入游戏，并使用控制台编辑存档</li><li>保存游戏，将游戏存档文件复制到模组中的 &quot;scenarios&quot; 文件夹</li></ul><h2 id="控制台" tabindex="-1">控制台 <a class="header-anchor" href="#控制台" aria-label="Permalink to &quot;控制台&quot;">​</a></h2><h3 id="打开控制台" tabindex="-1">打开控制台 <a class="header-anchor" href="#打开控制台" aria-label="Permalink to &quot;打开控制台&quot;">​</a></h3><p>要从世界屏幕打开控制台，请点击键盘上的反引号键 `。</p><p>在移动设备上：</p><ul><li>长按菜单汉堡包按钮（3 条线）</li><li>点击 &quot;developer console&quot; 按钮</li></ul><p>要查看可用命令，按回车键。这也适用于子命令（例如，当你输入 <code>tile</code> 时）。</p><h3 id="命令格式" tabindex="-1">命令格式 <a class="header-anchor" href="#命令格式" aria-label="Permalink to &quot;命令格式&quot;">​</a></h3><p>对象名称（单位、建筑、文明等）不区分大小写。</p><p>包含空格的单位名称和建筑名称，如 &quot;Great General&quot;，可以通过两种方式输入：</p><ul><li><strong>&quot;great general&quot;</strong> - 用引号包围</li><li><strong>great-general</strong> - 用破折号代替空格</li></ul><h3 id="自动补全" tabindex="-1">自动补全 <a class="header-anchor" href="#自动补全" aria-label="Permalink to &quot;自动补全&quot;">​</a></h3><p>控制台具有自动补全功能 - 对于命令和参数，使用 Tab 键。</p><ul><li>当两个或多个选项匹配时，会显示可能性，并为你输入最长的公共子字符串（例如，你输入 &#39;c&#39;，按 Tab：命令 &#39;city&#39; 或 &#39;civ&#39; 匹配，控制台为你部分完成 &#39;ci&#39;）。</li><li>当你尚未输入部分文本（控制台输入为空或以空格结尾）时，自动补全将显示所有选项。</li></ul><h3 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h3><p>某些命令操作于你需要在地图上选择的地块或单位。你也可以在控制台打开时这样做。</p><p>控制台有意不遵循规则集定义的所有规则 - 例如，它允许在没有淡水的山上建造农场，或者让工人拥有机动性晋升。任何意外后果由你负责。</p><p>你可以使用上/下箭头键访问命令历史记录。</p>',23)])])}const q=e(l,[["render",i]]);export{u as __pageData,q as default};
